LogicDefinition.ScriptText:
#load "reference"

using EMSPlugin.SceneObjects;
using FS.SDK.Components;


// #######################################################################################################################
// Zur automatischen Umbenennung aller LableObjects und automatischer Beschriftung dieser, wenn "UseSolt" aktiviert wurde.
// Das Label liegt dabei als Kind unter dem Objekt das benannt werden soll. Die Funktion sucht den Parentnamen und
// benennt das Label mitsamt TextSlot um.
// #######################################################################################################################

if (Enable && !EnableTrigger)
{
    // sucht alle LabelObjects
    foreach (var Label in SceneObject.Universe.GetAll().OfType<LabelObject>())
    {
            // Text des LabelObjekts wird gesetzt wenn "UseSlot" in den Properties LabelComponents
            if (Label.GetComponent<IOSlotContainerComponent>() is { } slotContainer &&
                        slotContainer.SlotsByName.TryGetValue("Text", out var slot) &&
                        slot is IOSlot<string> TextSlot)
            {

                string LabelParent = Label.Parent.Name;

                // hol den Namen des Parent und ändere Name des Labels
                Label.Name = $"Label_{LabelParent}";

                // ändere TextSlot des Labels
                TextSlot.Value = LabelParent;

                // Ausgabe Logger
                Logger.I($"Objektname und TextSlot wurden umbenannt:  {TextSlot.Value}");
             }

    }
}
// Trigger
EnableTrigger = Enable;
